def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_last = opp[-1]
    me_last = me[-1]

    cc = dd = cd = dc = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
        elif a == 'C' and b == 'D':
            cd += 1
        else:
            dc += 1

    opp_c = cc + dc
    opp_d = n - opp_c
    my_c = cc + cd

    if n >= 97:
        if opp_c >= n * 0.7:
            return 'D'
        if opp_d > n * 0.5:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C' if cc >= n * 0.5 else 'D'

    if n >= 5 and dd >= n - 1:
        return 'D'
    if n >= 6 and opp_d >= n - 1:
        return 'D'

    recent = opp[-6:]
    recent_d = recent.count('D')
    recent_c = len(recent) - recent_d

    if n >= 5 and opp_c >= n - 1 and dc <= 1:
        if n >= 12 and opp_c >= n * 0.9 and my_c > n * 0.5:
            if rng.random() < 0.10:
                return 'D'
        return 'C'

    if n >= 10 and recent_d >= 5:
        return 'D'

    if n >= 8 and opp_d <= 1 and cd <= 1:
        if opp_last == 'C' and rng.random() < 0.06:
            return 'D'
        return 'C'

    if dd >= 2 and cc == 0 and opp_d > n * 0.6:
        return 'D' if rng.random() < 0.9 else 'C'

    if opp_last == 'C':
        if opp_d >= 3 and recent_d >= 2:
            if rng.random() < 0.5:
                return 'D'
        if n >= 10 and opp_d == 0 and my_c >= n - 1:
            if rng.random() < 0.08:
                return 'D'
        return 'C'

    coop_rate = (cc + dc) / n
    if cd >= 1 and cc >= 1:
        if cd >= 3 and (cc + cd) >= n * 0.4 and rng.random() < 0.3:
            return 'C'
    if coop_rate > 0.55:
        if rng.random() < 0.35:
            return 'C'
        return 'D'
    if coop_rate > 0.25:
        if len(history) >= 2 and opp[-2] == 'D' and recent_d >= 3:
            return 'D'
        return 'D' if rng.random() < 0.65 else 'C'
    if rng.random() < 0.9:
        return 'D'
    return 'C'
